		getimagesize( $uploaded_tmp ) ) {
		if( !move_uploaded_file( $uploaded_tmp, $target_path ) ) {", "source": "multipart/form-data 上传字段 `uploaded` 的文件名与文件内容", "source_kind": "upload", "source_name": "uploaded", "tainted_expression": "$_FILES['uploaded']['name'] / $_FILES['uploaded']['tmp_name']", "sink": "move_uploaded_file($uploaded_tmp, $target_path) 写入 DVWA_WEB_PAGE_TO_ROOT."hackable/uploads/" 目录", "endpoint": "/vulnerabilities/upload/ (043.php)", "http_method": "POST", "exploit_chain": [{"step": 1, "location": "043.php:3", "description": "检测到 POST 参数 Upload，进入上传处理分支", "data_state": "攻击者控制 multipart 请求"}, {"step": 2, "location": "043.php:9-12", "description": "从 $_FILES['uploaded'] 读取文件名、扩展名、大小、临时路径", "data_state": "文件名与内容完全由攻击者控制"}, {"step": 3, "location": "043.php:15-17", "description": "校验扩展名为 jpg/jpeg/png、大小 <100000、getimagesize 通过", "data_state": "polyglot 文件（合法图片头 + PHP 尾）可通过", "bypass_reason": "getimagesize 仅校验文件头，不校验文件其余内容；扩展名取自文件名最后一段，攻击者可直接命名为 shell.png"}, {"step": 4, "location": "043.php:5-6", "description": "目标路径 = 上传目录 + basename(文件名)", "data_state": "basename 去除路径分隔符，但保留文件名与扩展名"}, {"step": 5, "location": "043.php:20", "description": "move_uploaded_file 将临时文件移动到 web 可访问的 hackable/uploads/ 目录", "data_state": "恶意文件落盘为 web 可访问资源"}], "poc": {"description": "构造带合法 PNG 头、尾部含 PHP 代码的 polyglot 文件，以 shell.png 为文件名上传，随后访问上传路径触发 PHP 执行（仅限授权测试）", "preconditions": ["目标为 DVWA 部署，hackable/uploads/ 目录可写且位于 web 根下", "服务器对 uploads 目录下文件按扩展名解析（若仅按 .php 解析则需配合解析配置，属运行时条件）", "无需认证（若 DVWA 未启用登录）或需低权限登录"], "steps": [{"step": 1, "action": "上传 polyglot 图片文件", "request": "POST /vulnerabilities/upload/ HTTP/1.1
